Mesh<Point, double> result;

for (auto eit = rt.finite_edges_begin(); eit != rt.finite_edges_end(); ++eit) {
    if (is_small_edge(rt, *eit, threshold)) {
        // Collect incident cells as polygons
        std::vector<unsigned> polygon;
        auto const &e = *eit;
        auto const &c = e.first;
        auto const &i = e.second;
        auto const &j = e.third;

        // Get the vertices of the edge
        std::vector<unsigned> edge_vertices;
        edge_vertices.push_back(c->vertex(i)->info());
        edge_vertices.push_back(c->vertex(j)->info());

        // In 3D, an edge is incident to several faces. We walk around the edge
        // and collect the dual faces (which are the vertices of the power diagram face)
        // In CGAL, we can use the fact that each edge connects two vertices in the triangulation
        // and is incident to several tetrahedra that form the face of the power diagram.
        // For a regular triangulation, the power diagram face is the dual of this edge,
        // which is formed by the vertices of the cells incident to the edge.

        // Iterate over the cells incident to the edge
        // and collect the indices of the dual vertices
        // The dual vertex in the power diagram is the vertex of the adjacent cell
        // that is not on the edge.
        RT::Vertex_handle v1 = c->vertex(i);
        RT::Vertex_handle v2 = c->vertex(j);

        // We want to collect all the cells that are incident to this edge.
        // In 3D, an edge is the intersection of two faces of a tetrahedron.
        // The dual of the edge in the power diagram is the face that is the convex hull
        // of all the dual points of incident cells.
        std::vector<RT::Vertex_handle> edge_vhandles;
        edge_vhandles.push_back(v1);
        edge_vhandles.push_back(v2);

        // Collect the vertices of the power diagram face (which are the dual points
        // of the cells incident to the edge)
        std::vector<unsigned> dual_vertices;
        for (auto vit : edge_vhandles) {
            dual_vertices.push_back(vit->info());
        }

        // The 'dual' of the edge is the segment connecting the two vertices
        // The power diagram face is the convex hull of the dual points of the
        // cells incident to the edge. In this case, it's just the two vertices
        // of the edge.
        if (dual_vertices.size() >= 2) {
            // Add the face to the mesh
            result.push_back(dual_vertices, rt.segment(*eit).squared_length());
        }
    }
}

return result;

